module logic;
use model {Summary,Job};
use util {reverse};

record IdScan {pending:List<I64>,matched:Bool}
record Choice {pending:List<Job>,best:Job}
record Schedule {order:List<I64>,remaining:I64,active:Bool}

fn contains_id(ids:List<I64>,target:I64)->Bool {
 let found=fold(i in List::length(ids),scan:IdScan=IdScan {pending:ids,matched:false}) {
  IdScan {pending:List::tail(scan.pending),matched:scan.matched || List::head(scan.pending)==target}
 };
 found.matched
}

fn dependencies_done(deps:List<I64>,completed:List<I64>)->Bool {
 let checked=fold(i in List::length(deps),scan:IdScan=IdScan {pending:deps,matched:true}) {
  IdScan {pending:List::tail(scan.pending),matched:scan.matched && contains_id(completed,List::head(scan.pending))}
 };
 checked.matched
}

fn choose(jobs:List<Job>,completed:List<I64>,remaining:I64)->Job {
 let selected=fold(i in List::length(jobs),scan:Choice=Choice {
  pending:jobs,best:Job {id:List::length(jobs),cost:0,deps:List::empty<I64>()}
 }) {
  let candidate=List::head(scan.pending);
  let eligible=candidate.id<scan.best.id && candidate.cost<=remaining && !contains_id(completed,candidate.id) && dependencies_done(candidate.deps,completed);
  Choice {pending:List::tail(scan.pending),best:if eligible {candidate} else {scan.best}}
 };
 selected.best
}

fn run(jobs:List<Job>,budget:I64)->Summary {
 let count=List::length(jobs);
 let final=while(state:Schedule=Schedule {order:List::empty<I64>(),remaining:budget,active:true}; state.active && List::length(state.order)<count) {
  let next=choose(jobs,state.order,state.remaining);
  if next.id<count {
   Schedule {order:List::prepend(next.id,state.order),remaining:state.remaining-next.cost,active:true}
  } else {
   Schedule {...state,active:false}
  }
 };
 Summary {order:reverse(final.order),spent:budget-final.remaining,blocked:count-List::length(final.order)}
}

